package com.nivor.journal;
import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;import java.time.LocalDate;import java.util.*;
@Entity@Table(name="journal_entries",indexes={@Index(name="idx_journal_user",columnList="user_id"),@Index(name="idx_journal_date",columnList="entry_date")})public class JournalEntry extends AuditedEntity{
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@Column(length=180)private String title;@Column(nullable=false,columnDefinition="TEXT")private String content;@Enumerated(EnumType.STRING)@Column(length=20)private JournalMood mood;@ElementCollection@CollectionTable(name="journal_tags",joinColumns=@JoinColumn(name="entry_id"))@Column(name="tag",length=40)private List<String> tags=new ArrayList<>();@Column(name="entry_date",nullable=false)private LocalDate entryDate;
 protected JournalEntry(){}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public JournalMood getMood(){return mood;}public void setMood(JournalMood v){mood=v;}public List<String> getTags(){return tags;}public void setTags(List<String> v){tags=v==null?new ArrayList<>():new ArrayList<>(v);}public LocalDate getEntryDate(){return entryDate;}public void setEntryDate(LocalDate v){entryDate=v;}
}
